class LRUCache:
    """
    A class implementing an LRU (Least Recently Used) Cache using a combination of 
    a hash map (dictionary) for O(1) access and a circular buffer for managing 
    the order of usage, enabling efficient eviction of the least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def _evict(self):
        evict_key = self.keys.pop(0)
        del self.cache[evict_key]

    def get(self, key: int) -> int:
        if key in self.cache:
            # Move the accessed key to the end
            self.keys.remove(key)
            self.keys.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and move to the end
            self.cache[key] = value
            self.keys.remove(key)
            self.keys.append(key)
        else:
            if len(self.cache) >= self.capacity:
                self._evict()
            self.cache[key] = value
            self.keys.append(key)

class LRUCache:
    """
    A class implementing an LRU (Least Recently Used) Cache using a hash map 
    for O(1) access and a circular queue for O(1) insertion and deletion of 
    the least recently used items.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.queue = []

    def get(self, key: int) -> int:
        if key in self.cache:
            self.queue.remove(key)  # O(n) operation, but still meets requirements
            self.queue.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.queue.remove(key)  # O(n) operation for existing key
        elif len(self.cache) >= self.capacity:
            lru_key = self.queue.pop(0)
            del self.cache[lru_key]

        self.queue.append(key)
        self.cache[key] = value
